"""Collect paper tables from predictions generated by the two experiment runs."""

from pathlib import Path
import numpy as np

from .io import read, rows, write
from .metrics import summarize_prediction, mean_sd, comparison, holm
from .tables import cells, MODELS


def prediction(path, uids):
    with np.load(path) as saved:
        data = dict(saved)
    np.testing.assert_array_equal(data["uids"], uids)
    for key, value in data.items():
        if key.startswith("pred_") or key == "pred":
            if value.shape != (len(uids),) or not np.isin(value, [0, 1, 2]).all():
                raise ValueError(f"Invalid predictions: {path}, {key}")
    return data


def summarize(evidence_dir, baseline_dir, data_dir, output):
    evidence_dir, baseline_dir, output = map(Path, [evidence_dir, baseline_dir, output])
    evidence_plan = read(evidence_dir / "plan.json")
    baseline_plan = read(baseline_dir / "plan.json")
    if evidence_plan["data_hashes"] != baseline_plan["data_hashes"]:
        raise ValueError("The two runs must use identical data")
    seeds = evidence_plan["config"]["seeds"]
    if seeds != baseline_plan["config"]["seeds"]:
        raise ValueError("The two runs must use identical seeds")
    if baseline_plan["config"]["fairsteer_backend"] != "cuml":
        raise ValueError("Paper baseline tables require author cuML FairSteer")
    from .data import audit

    audit(data_dir, seeds)
    from .io import sha

    if sha(Path(data_dir) / "test.jsonl") != evidence_plan["data_hashes"]["test.jsonl"]:
        raise ValueError("Test data differ from the experiment plan")
    values = rows(Path(data_dir) / "test.jsonl")
    uids = [r["uid"] for r in values]
    zero = np.zeros(len(values), bool)
    result = {"seeds": seeds, "models": {}, "comparison_groups": {}}
    all_predictions = {}
    policies = [
        "egus_layer_selected",
        "evidence_joint_selected",
        "evidence_at_egus_layer",
        "egus_at_evidence_layer",
    ]
    for model in MODELS:
        spec = {"per_seed": {}, "selections": {}}
        predictions = {}
        for seed in seeds:
            ep, bp = [p / model / f"seed_{seed}" for p in [evidence_dir, baseline_dir]]
            e, b = [prediction(p / "predictions.npz", uids) for p in [ep, bp]]
            chosen = read(ep / "selection.json")["selected"]
            spec["selections"][str(seed)] = {k: chosen[k] for k in policies}
            spec["selections"][str(seed)]["fs_joint_selected"] = read(bp / "selection.json")[
                "selected"
            ]["fs_joint_selected"]
            sources = {k: (e["pred_" + k], e["trigger_" + k]) for k in policies}
            sources.update(
                base=(b["pred_base"], zero),
                evidence_base=(e["pred_base"], zero),
                fs_joint_selected=(b["pred_fs_joint_selected"], b["trigger_fs_joint_selected"]),
            )
            metrics = {}
            for policy, (pred, mask) in sources.items():
                metrics[policy] = summarize_prediction(values, pred, mask)
                predictions.setdefault(policy, []).append(pred)
            spec["per_seed"][str(seed)] = metrics
        spec["aggregate"] = {
            policy: {
                metric: mean_sd([r[policy][metric] for r in spec["per_seed"].values()])
                for metric in ["accuracy", "ambig", "clear"]
            }
            for policy in predictions
        }
        kb = prediction(baseline_dir / model / "knowbias_predictions.npz", uids)
        spec["knowbias"] = {
            "independent_fits": 1,
            "metrics": summarize_prediction(values, kb["pred"], zero),
            "selected": read(baseline_dir / model / "knowbias_selection.json")["selected"],
        }
        a, b = predictions["base"][0], predictions["evidence_base"][0]
        spec["base_execution_differences"] = [
            {"uid": uids[i], "native_prediction": int(a[i]), "evidence_prediction": int(b[i])}
            for i in np.flatnonzero(a != b)
        ]
        result["models"][model] = spec
        all_predictions[model] = {k: np.stack(v) for k, v in predictions.items()}
    for group, models in [("small", MODELS[:3]), ("extended", MODELS[3:])]:
        contrasts = {
            model + ":" + policy: comparison(
                values,
                all_predictions[model]["egus_layer_selected"],
                all_predictions[model][policy],
            )
            for model in models
            for policy in ["fs_joint_selected", "evidence_joint_selected"]
        }
        holm(contrasts)
        result["comparison_groups"][group] = contrasts
    write(output / "summary.json", result)
    write(output / "tables.json", cells(result))
    return {"models": len(MODELS), "seeds": len(seeds), "output": str(output)}
